package cn.mop.api;
import cn.mop.domain.capacity.*;
import cn.mop.domain.capacity.CapacityScenarioDraft.BenchmarkReference;
import org.junit.jupiter.api.Test;
import java.math.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
/** Pure draft boundaries; no database, saved scenario, measurement or approved benchmark claim. */
class CapacityScenarioDraftTest {
    static CapacityCalculation unknown(){return new CapacityCalculation(null,null,null);}
    static CapacityCalculation known(){return new CapacityCalculation(new CapacityEstimate.Inputs(BigInteger.TEN,BigInteger.valueOf(100),new BigDecimal("10"),2,new BigDecimal("80"),new BigDecimal("0.5"),3,new BigDecimal("0.25")),new CapacityEstimate.Model("SYNTHETIC-v1",new BigDecimal("128"),new BigDecimal("60")),new ProxyBufferEstimate.Inputs(new BigDecimal("125"),new BigDecimal("3600"),new BigDecimal("80"),new BigDecimal("1.4")));}
    @Test void unknownDraftKeepsMissingValuesAndCannotClaimEffectiveOrMeasured(){var d=new CapacityScenarioDraft("明确草稿","明确说明",unknown(),null);assertEquals("DRAFT",d.lifecycleStatus());assertEquals("NOT_PROVIDED",d.benchmarkVerification());assertFalse(d.effective());assertFalse(d.productionCapacityVerified());assertFalse(d.pocExecuted());assertNull(d.calculation().snapshot().capacity().outputs());assertNull(d.calculation().snapshot().proxyBuffer().estimatedBytes());}
    @Test void knownDraftSnapshotsBothVersionedFormulasWithoutPrototypeDefaults(){var d=new CapacityScenarioDraft("明确草稿","说明",known(),null);var s=d.calculation().snapshot();assertEquals("contract-m10-7-capacity-v1",s.capacityFormulaVersion());assertEquals("contract-m4-15-buffer-v1",s.bufferFormulaVersion());assertEquals(0,new BigDecimal("1733760000").compareTo(s.capacity().outputs().singleNodeBytes()));assertEquals(0,new BigDecimal("50400000").compareTo(s.proxyBuffer().estimatedBytes()));assertFalse(s.proxyBuffer().measurementVerified());}
    @Test void optionalBaselineReferenceDoesNotMeanTheDocumentOrDigestWasVerified(){var ref=new BenchmarkReference("document-ref:SYNTHETIC-baseline-v1","虚构基准引用","A".repeat(64));var d=new CapacityScenarioDraft("草稿","说明",known(),ref);assertEquals("a".repeat(64),ref.sha256());assertEquals("REFERENCE_ONLY_UNVERIFIED",d.benchmarkVerification());assertFalse(d.pocExecuted());assertEquals(ref,d.benchmarkReference());}
    @Test void rawTextIsPreservedAndUnicodeLimitsAreCodePoints(){String label="  原文😀  ",note="  第一行\n第二行\t  ";var d=new CapacityScenarioDraft(label,note,unknown(),null);assertEquals(label,d.label());assertEquals(note,d.note());assertDoesNotThrow(()->new CapacityScenarioDraft("😀".repeat(100),"😀".repeat(2000),unknown(),null));assertThrows(IllegalArgumentException.class,()->new CapacityScenarioDraft("😀".repeat(101),"note",unknown(),null));assertThrows(IllegalArgumentException.class,()->new CapacityScenarioDraft("label","😀".repeat(2001),unknown(),null));}
    @Test void blankControlsMalformedUnicodeAndMissingCalculationFailClosed(){for(String value:Arrays.asList(null,""," \ufeff\u3000","x\n","x\ud800"))assertThrows(IllegalArgumentException.class,()->new CapacityScenarioDraft(value,"note",unknown(),null));for(String value:Arrays.asList(null,"","\u00a0","x\u0001"))assertThrows(IllegalArgumentException.class,()->new CapacityScenarioDraft("label",value,unknown(),null));assertThrows(IllegalArgumentException.class,()->new CapacityScenarioDraft("label","note",null,null));}
    @Test void referenceCannotCarryUrlDiskPathOrObviousSecretMarkers(){for(String ref:List.of("https://example.invalid/report","document-ref:C:report","document-ref:/tmp/report","document-ref:token-value","document-ref:password-value","document-ref:private_key-value","document-ref:credential-value"))assertThrows(IllegalArgumentException.class,()->new BenchmarkReference(ref,"title","a".repeat(64)));for(String hash:Arrays.asList(null,"","a".repeat(63),"g".repeat(64)))assertThrows(IllegalArgumentException.class,()->new BenchmarkReference("document-ref:valid","title",hash));}
    @Test void boundedCalculationKeepsFortyDigitCountsAndRejectsBeyondHttpMagnitude(){var i=known().inputs();assertDoesNotThrow(()->new CapacityCalculation(new CapacityEstimate.Inputs(BigInteger.TEN.pow(40).subtract(BigInteger.ONE),i.itemsPerHost(),i.intervalSeconds(),i.historyDays(),i.bytesPerValue(),i.trendRatio(),i.trendDays(),i.headroomRatio()),known().model(),null));assertThrows(IllegalArgumentException.class,()->new CapacityCalculation(new CapacityEstimate.Inputs(BigInteger.TEN.pow(40),i.itemsPerHost(),i.intervalSeconds(),i.historyDays(),i.bytesPerValue(),i.trendRatio(),i.trendDays(),i.headroomRatio()),known().model(),null));}
    @Test void decimalBoundsDenominatorsRatiosAndModelLabelUseExplicitRules(){for(BigDecimal value:List.of(new BigDecimal("1e41"),new BigDecimal("1e-41"),BigDecimal.ZERO,new BigDecimal("-1")))assertThrows(IllegalArgumentException.class,()->new CapacityCalculation(null,new CapacityEstimate.Model("model",value,BigDecimal.ONE),null));assertThrows(IllegalArgumentException.class,()->new CapacityCalculation(null,new CapacityEstimate.Model(" ",null,null),null));assertThrows(IllegalArgumentException.class,()->new CapacityCalculation(null,null,new ProxyBufferEstimate.Inputs(BigDecimal.ONE,BigDecimal.ONE,BigDecimal.ONE,BigDecimal.ZERO)));}
    @Test void snapshotsRejectUnknownFormulaVersionsAndMissingComputedGroups(){var s=known().snapshot();assertThrows(IllegalArgumentException.class,()->new CapacityCalculation.Snapshot("unreviewed",s.bufferFormulaVersion(),s.capacity(),s.proxyBuffer()));assertThrows(IllegalArgumentException.class,()->new CapacityCalculation.Snapshot(s.capacityFormulaVersion(),"unreviewed",s.capacity(),s.proxyBuffer()));assertThrows(IllegalArgumentException.class,()->new CapacityCalculation.Snapshot(s.capacityFormulaVersion(),s.bufferFormulaVersion(),null,s.proxyBuffer()));}
    @Test void wireCodecKeepsOriginalDecimalStringsAndUnknownGroups(){var source=known().wire();var inputs=(Map<String,Object>)source.get("inputs");inputs.put("interval_seconds","10.000");inputs.put("hosts","9007199254740993");var parsed=CapacityCalculation.fromWire(source);assertEquals("10.000",((Map<?,?>)parsed.wire().get("inputs")).get("interval_seconds"));assertEquals("9007199254740993",((Map<?,?>)parsed.wire().get("inputs")).get("hosts"));assertEquals(unknown(),CapacityCalculation.fromWire(unknown().wire()));inputs.put("hosts","1");assertEquals("9007199254740993",((Map<?,?>)parsed.wire().get("inputs")).get("hosts"));}
    @Test void wireCodecRejectsNumericCoercionExponentAndIncompleteObjects(){for(Object value:List.of(10L,10.0,"1e3","01","-1","0."+"1".repeat(41))){var source=known().wire();((Map<String,Object>)source.get("inputs")).put("interval_seconds",value);assertThrows(IllegalArgumentException.class,()->CapacityCalculation.fromWire(source));}var missing=known().wire();((Map<String,Object>)missing.get("model")).remove("pool_nvps_limit");assertThrows(IllegalArgumentException.class,()->CapacityCalculation.fromWire(missing));var extra=known().wire();extra.put("tenant_id","forged");assertThrows(IllegalArgumentException.class,()->CapacityCalculation.fromWire(extra));}
    @Test void wireDayNumbersMustBeIntegralBoundedAndNoFloats(){for(Object value:List.of("1",1.0,new BigDecimal("1.0"),2147483648L,-1L)){var source=known().wire();((Map<String,Object>)source.get("inputs")).put("history_days",value);assertThrows(IllegalArgumentException.class,()->CapacityCalculation.fromWire(source));}var source=known().wire();((Map<String,Object>)source.get("inputs")).put("history_days",BigInteger.valueOf(Integer.MAX_VALUE));assertEquals(Integer.MAX_VALUE,CapacityCalculation.fromWire(source).inputs().historyDays());}

}
